<?php

declare(strict_types=1);

namespace Inilim\Tool\Method\Other{function colorStrCli(string $text,string $colorHexText,?string $colorHexBackground=null,?string $style=null):string{$c=\Inilim\Tool\Method\Other\colorHexToRgb($colorHexText);$result=\sprintf("\x1b[38;2;%s;%s;%sm",$c['red'],$c['green'],$c['blue']);if($colorHexBackground!==null){$b=\Inilim\Tool\Method\Other\colorHexToRgb($colorHexBackground);$result .= \sprintf("\x1b[48;2;%s;%s;%sm",$b['red'],$b['green'],$b['blue']);}if($style!==null){$style=\strtolower($style);$styles=['bold'=>"\x1b[1m",'un_bold'=>"\x1b[21m",'dim'=>"\x1b[2m",'un_dim'=>"\x1b[22m",'underlined'=>"\x1b[4m",'un_underlined'=>"\x1b[24m",'blink'=>"\x1b[5m",'un_blink'=>"\x1b[25m",'reverse'=>"\x1b[7m",'un_reverse'=>"\x1b[27m",'hidden'=>"\x1b[8m",'un_hidden'=>"\x1b[28m"];$s=$styles[$style]?? null;if($s===null){throw new \InvalidArgumentException('Value error $style');}$result .= $s;}return $result.$text."\x1b[0m";}if(!\Inilim\Tool\Other::__definedIfNot('colorHexToRgb')){
    function colorHexToRgb(string $hex):array{$hex=\strtolower(\ltrim($hex,'#'));if(\strlen($hex)===3){$r=\hexdec(\substr($hex,0,1).\substr($hex,0,1));$g=\hexdec(\substr($hex,1,1).\substr($hex,1,1));$b=\hexdec(\substr($hex,2,1).\substr($hex,2,1));}else{$r=\hexdec(\substr($hex,0,2));$g=\hexdec(\substr($hex,2,2));$b=\hexdec(\substr($hex,4,2));}return['red'=>(int) $r,'green'=>(int) $g,'blue'=>(int) $b];}
    }}